// src/content/bank/index.ts
function splitAnswers(raw) {
  return raw.split("|").map((a) => a.trim()).filter(Boolean);
}
function slug(text) {
  return normalizeAnswer(text).replace(/\s+/g, "-");
}
function letterOf(raw) {
  if (!isLetter(raw)) throw new Error(`Letra no v\xE1lida en el banco: ${raw}`);
  return raw;
}
function loadBank() {
  const rosco = [...ROSCO_A_F, ...ROSCO_G_M, ...ROSCO_N_R, ...ROSCO_S_Z].map(
    ([letter, mode, answers, definition, difficulty]) => {
      const list = splitAnswers(answers);
      return {
        id: `r-${slug(letter)}-${mode}-${slug(list[0] ?? "")}`,
        prompt: { kind: "rosco", letter: letterOf(letter), mode: mode === "s" ? "starts" : "contains", definition },
        answers: list,
        difficulty
      };
    }
  );
  const quick = QUICK_BANK.map(([definition, answers, difficulty]) => ({
    id: `q-${shortHash(definition)}`,
    prompt: { kind: "quick", definition },
    answers: splitAnswers(answers),
    difficulty
  }));
  const clues = CLUES_BANK.map(([clueList, answers, difficulty]) => ({
    id: `c-${shortHash(clueList.join("|"))}`,
    prompt: { kind: "clues", clues: [...clueList] },
    answers: splitAnswers(answers),
    difficulty
  }));
  const saying = SAYINGS_BANK.map(([text, answers, difficulty]) => ({
    id: `s-${shortHash(text)}`,
    prompt: { kind: "saying", text },
    answers: splitAnswers(answers),
    difficulty
  }));
  const link = LINKS_BANK.map(([words, answers, difficulty]) => ({
    id: `l-${shortHash(words.join("|"))}`,
    prompt: { kind: "link", words: [...words] },
    answers: splitAnswers(answers),
    difficulty
  }));
  return { rosco, quick, clues, saying, link };
}
var cached2 = null;
function getBank() {
  cached2 ??= loadBank();
  return cached2;
}
function bankVersion(bank = getBank()) {
  return `bank-${shortHash(JSON.stringify(bank))}`;
}

