import { createHash, createHmac, randomBytes as randomBytes2, timingSafeEqual } from "node:crypto";
var IDENTITY_MAX_AGE_SECONDS = 400 * 24 * 60 * 60;

// src/lib/server/players.ts
async function playerFromAuthUser(db, authUserId) {
  if (!/^[0-9a-f-]{36}$/i.test(authUserId)) return null;
  const select = () => db.query(
    `select id, display_name, name_is_custom, last_seen_at < now() - interval '10 minutes' as stale
         from anonymous_players where auth_user_id = $1`,
    [authUserId]
  );
  let row = (await select()).rows[0];
  if (!row) {
    await db.query(
      `insert into anonymous_players (auth_user_id, display_name) values ($1, $2) on conflict (auth_user_id) do nothing`,
      [authUserId, defaultDisplayName(authUserId)]
    );
    row = (await select()).rows[0];
  } else if (row.stale) {
    await db.query("update anonymous_players set last_seen_at = now() where id = $1", [row.id]);
  }
  if (!row) return null;
  return { id: row.id, displayName: row.display_name, nameIsCustom: row.name_is_custom };
}

// src/edge/main.ts
function env(name) {
  const value = Deno.env.get(name);
  if (!value) throw new Error(`Falta la variable de entorno ${name}`);
  return value;
}
function startEdgeServer() {
  const supabaseUrl = env("SUPABASE_URL");
  const anonKey = env("SUPABASE_ANON_KEY");
  const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  const auth = createClient(supabaseUrl, anonKey, {
    auth: { persistSession: false, autoRefreshToken: false, detectSessionInUrl: false }
  }).auth;
  let dbPromise = null;
  const getDb = () => dbPromise ??= createPostgres(env("SUPABASE_DB_URL"), { poolSize: 3 });
  setDefaultDatabase(getDb);
  if (serviceKey) {
    setRoomPublisher(async (room) => {
      const res = await fetch(`${supabaseUrl}/realtime/v1/api/broadcast`, {
        method: "POST",
        headers: { apikey: serviceKey, Authorization: `Bearer ${serviceKey}`, "Content-Type": "application/json" },
        body: JSON.stringify({ messages: [{ topic: `room-${room.code}`, event: "update", payload: { at: Date.now() } }] }),
        signal: AbortSignal.timeout(2e3)
      });
      if (!res.ok) throw new Error(`Broadcast ${res.status}`);
    });
  }
  const allowed = (Deno.env.get("ALLOWED_ORIGINS") ?? "*").trim();
  const handler = createApiHandler({
    getDb,
    allowedOrigins: allowed === "*" ? "*" : allowed.split(",").map((o) => o.trim()),
    background: (task) => {
      if (typeof EdgeRuntime !== "undefined") EdgeRuntime.waitUntil(task);
    },
    authenticate: async (request, db) => {
      const token = bearerToken(request);
      if (!token) return null;
      const { data, error: error62 } = await auth.getClaims(token);
      const sub = data?.claims?.sub;
      if (error62 || typeof sub !== "string") return null;
      return playerFromAuthUser(db, sub);
    }
  });
  Deno.serve(handler);
}
